def run(p):
 n=p['number'];t=ts[p['head']['ref']];jobs=[('gates',['gh','api',f"repos/entireio/entire-brain/commits/{p['head']['sha']}/check-runs"]),('discussion',['entire','trail','comment','list','--trail',str(t['number']),'--repo','gh/entireio/entire-brain','--json']),('approvals',['entire','trail','approvals',str(t['number']),'--repo','gh/entireio/entire-brain','--json'])]
